mapper.insert:
INSERT INTO oa_iam.authz_decision_log (
    tenant_id, command_id, trace_id, caller_user_id, principal_id, identity_type,
    resource_type, resource_id, action, decision, policy_id, reason, evaluated_at
) VALUES (
    #{tenantId}, #{commandId}, #{traceId}, #{callerUserId}, CAST(#{principalId} AS uuid),
    #{identityType}, #{resourceType}, #{resourceId}, #{action}, #{decision},
    #{policyId}, #{reason}, #{evaluatedAt}
)

mapper.select:
SELECT id, tenant_id AS tenantId, command_id AS commandId, trace_id AS traceId,
       caller_user_id AS callerUserId, principal_id AS principalId,
       identity_type AS identityType, resource_type AS resourceType,
       resource_id AS resourceId, action, decision, policy_id AS policyId,
       reason, evaluated_at AS evaluatedAt
  FROM oa_iam.authz_decision_log
 WHERE tenant_id = #{tenantId}

   AND principal_id = CAST(#{principalId} AS uuid)


   AND decision = #{decision}


   AND id > #{cursor}

 ORDER BY id
 LIMIT #{limit}
